<?php
namespace App\Http\Controllers\Api\V1\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\StoreCatalogItemRequest; use App\Http\Requests\UpdateCatalogItemRequest; use App\Http\Resources\PackageResource; use App\Models\Package; use Illuminate\Http\Request;
class PackageController extends Controller { public function index(Request $request) { $q=Package::query(); if($request->filled('search'))$q->where('name','like','%'.$request->search.'%'); return PackageResource::collection($q->get()); } public function store(StoreCatalogItemRequest $request) { $data=$request->validated(); $data['image']=$this->upload($request); return (new PackageResource(Package::create($data)))->response()->setStatusCode(201); } public function show(Package $package) { return new PackageResource($package); } public function update(UpdateCatalogItemRequest $request,Package $package) { $data=$request->validated(); if($request->hasFile('image'))$data['image']=$this->upload($request); $package->update($data); return new PackageResource($package); } public function destroy(Package $package) { $package->delete(); return response()->json(status:204); } private function upload(Request $request):string { $name=$request->file('image')->getClientOriginalName(); $request->file('image')->move(public_path('images/package-images'),$name); return $name; } }
